// DeleteUniqueIndexCache 删除索引存在的缓存
func (s *SubOrderRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.SubOrder) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, s.cache.Key(CacheSubOrderByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[s.cache.Key(CacheSubOrderByIDPrefix, item.ID)] = struct{}{}
			KeyMap[s.cache.Key(CacheSubOrderByOrderNumberPrefix, item.OrderNumber)] = struct{}{}
			KeyMap[s.cache.Key(CacheSubOrderByGoodIDPrefix, item.GoodID)] = struct{}{}
			KeyMap[s.cache.Key(CacheSubOrderByOriginOrderNumberPrefix, item.OriginOrderNumber)] = struct{}{}
			KeyMap[s.cache.Key(CacheSubOrderByParentOrderIDPrefix, item.ParentOrderID)] = struct{}{}
			KeyMap[s.cache.Key(CacheSubOrderByPhPrefix, item.Ph)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := s.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
